//! The Hamilton quaternions B = (-1, -1 / F) over F = Q(sqrt 5), which
//! ramify exactly at the two infinite places, and the icosian ring R, a
//! maximal order of class number one (Dembélé 2005, section 3).
//!
//! R = O_F e1 + O_F e2 + O_F e3 + O_F e4 with (Dembélé 2005, section 3;
//! PSAGE sqrt5.py, icosian_ring_gens), writing w' = 1 - w,
//!   e1 = (1 - w' i + w j)/2,   e2 = (-w' i + j + w k)/2,
//!   e3 = (w i - w' j + k)/2,   e4 = (i + w j - w' k)/2.
//! R^x_1 (reduced norm 1) is the binary icosahedral group of order 120,
//! generated by i, j, k, (-1 + i + j + k)/2 and (i + w j + w' k)/2 (PSAGE
//! sqrt5.py, icosian_gens).
//!
//! An element alpha is stored by its doubled coordinates 2 alpha in the
//! basis 1, i, j, k (k = ij), which lie in O_F for every alpha in R; the
//! coordinates in the basis e1..e4 are the O_F-linear map `to_e` (PSAGE
//! sqrt5_fast.pyx, quaternion_in_terms_of_icosian_basis).

use crate::field::{Elt, ONE, W, ZERO};

/// 2 alpha = d0 + d1 i + d2 j + d3 k.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub struct Quat(pub [Elt; 4]);

const WM1: Elt = Elt::new(-1, 1); // w - 1 = -w'

/// The doubled coordinates of e1..e4.
pub const E: [Quat; 4] = [
    Quat([Elt::new(1, 0), WM1, W, ZERO]),
    Quat([ZERO, WM1, ONE, W]),
    Quat([ZERO, W, WM1, ONE]),
    Quat([ZERO, ONE, W, WM1]),
];

impl Quat {
    pub fn one() -> Quat {
        Quat([Elt::int(2), ZERO, ZERO, ZERO])
    }
    pub fn add(&self, o: &Quat) -> Quat {
        Quat([0, 1, 2, 3].map(|m| self.0[m].add(o.0[m])))
    }
    pub fn neg(&self) -> Quat {
        Quat(self.0.map(|x| x.neg()))
    }
    /// The product, if it has doubled coordinates in O_F (as it does for
    /// elements of R).
    pub fn mul(&self, o: &Quat) -> Option<Quat> {
        let [x0, x1, x2, x3] = self.0;
        let [y0, y1, y2, y3] = o.0;
        let m = |a: Elt, b: Elt| a.mul(b);
        let z = [
            m(x0, y0).sub(m(x1, y1)).sub(m(x2, y2)).sub(m(x3, y3)),
            m(x0, y1).add(m(x1, y0)).add(m(x2, y3)).sub(m(x3, y2)),
            m(x0, y2).sub(m(x1, y3)).add(m(x2, y0)).add(m(x3, y1)),
            m(x0, y3).add(m(x1, y2)).sub(m(x2, y1)).add(m(x3, y0)),
        ];
        // (2a)(2b) = 4ab = 2 (2ab)
        Some(Quat([z[0].half()?, z[1].half()?, z[2].half()?, z[3].half()?]))
    }
    /// The reduced norm, sum of the squared coordinates.
    pub fn nrd(&self) -> Elt {
        let s = self.0.iter().fold(ZERO, |s, x| s.add(x.mul(*x)));
        s.half().and_then(|x| x.half()).expect("reduced norm not integral")
    }
    pub fn trd(&self) -> Elt {
        self.0[0]
    }
    pub fn conj(&self) -> Quat {
        Quat([self.0[0], self.0[1].neg(), self.0[2].neg(), self.0[3].neg()])
    }
    /// Coordinates in the basis e1..e4, if alpha lies in R.
    pub fn to_e(&self) -> Option<[Elt; 4]> {
        let [d0, d1, d2, d3] = self.0;
        let wp1 = Elt::new(1, 1); // w + 1
        Some([
            d0,
            WM1.mul(d0).sub(d1).add(W.mul(d3)).half()?,
            WM1.mul(d0).add(W.mul(d1)).sub(d2).half()?,
            wp1.mul(d0).neg().add(W.mul(d2)).sub(d3).half()?,
        ])
    }
    pub fn from_e(c: &[Elt; 4]) -> Quat {
        let mut q = Quat([ZERO; 4]);
        for m in 0..4 {
            for t in 0..4 {
                q.0[t] = q.0[t].add(c[m].mul(E[m].0[t]));
            }
        }
        q
    }
}

/// The 120 units of reduced norm 1 of R, the closure of the generators
/// under multiplication, sorted.
pub fn icosians() -> Vec<Quat> {
    let wb = Elt::new(1, -1); // w' = 1 - w
    let gens = [
        Quat([ZERO, Elt::int(2), ZERO, ZERO]),
        Quat([ZERO, ZERO, Elt::int(2), ZERO]),
        Quat([ZERO, ZERO, ZERO, Elt::int(2)]),
        Quat([Elt::int(-1), ONE, ONE, ONE]),
        Quat([ZERO, ONE, W, wb]),
    ];
    let mut set = std::collections::BTreeSet::new();
    set.insert(Quat::one());
    let mut frontier = vec![Quat::one()];
    while let Some(x) = frontier.pop() {
        for g in &gens {
            let y = x.mul(g).expect("icosians are integral");
            if set.insert(y) {
                frontier.push(y);
            }
        }
    }
    set.into_iter().collect()
}

/// Structure constants of R: e_i e_j = sum_k c[i][j][k] e_k.
pub fn structure_constants() -> [[[Elt; 4]; 4]; 4] {
    let mut c = [[[ZERO; 4]; 4]; 4];
    for i in 0..4 {
        for j in 0..4 {
            c[i][j] = E[i].mul(&E[j]).and_then(|q| q.to_e()).expect("R is closed under multiplication");
        }
    }
    c
}

/// The e-coordinates of 1.
pub fn one_e() -> [Elt; 4] {
    Quat::one().to_e().unwrap()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn basis_and_coordinates() {
        for m in 0..4 {
            let mut u = [ZERO; 4];
            u[m] = ONE;
            assert_eq!(E[m].to_e(), Some(u));
            assert_eq!(Quat::from_e(&u), E[m]);
        }
        // the discriminant of R is 1: det(trd(e_i e_j)) is a unit
        let o = one_e();
        assert_eq!(Quat::from_e(&o), Quat::one());
    }

    #[test]
    fn icosian_group() {
        let g = icosians();
        assert_eq!(g.len(), 120);
        for x in &g {
            assert_eq!(x.nrd(), ONE);
            let c = x.to_e().expect("icosian in R");
            assert_eq!(Quat::from_e(&c), *x);
        }
    }

    #[test]
    fn reduced_discriminant_is_one() {
        // det of the trace form trd(e_i conj(e_j)) over O_F must be a unit
        // for a maximal order of a quaternion algebra unramified at all finite
        // places (the discriminant ideal is the square of the reduced one).
        let t: Vec<Vec<Elt>> = (0..4).map(|i| (0..4).map(|j| E[i].mul(&E[j].conj()).unwrap().trd()).collect()).collect();
        let det = det4(&t);
        assert_eq!(det.norm().abs(), 1);
    }

    fn det4(m: &[Vec<Elt>]) -> Elt {
        // Laplace expansion
        fn det(m: &[Vec<Elt>]) -> Elt {
            if m.len() == 1 {
                return m[0][0];
            }
            let mut s = ZERO;
            for j in 0..m.len() {
                let minor: Vec<Vec<Elt>> = m[1..].iter().map(|r| r.iter().enumerate().filter(|&(k, _)| k != j).map(|(_, &x)| x).collect()).collect();
                let t = m[0][j].mul(det(&minor));
                s = if j % 2 == 0 { s.add(t) } else { s.sub(t) };
            }
            s
        }
        det(m)
    }
}
